local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[405906]=b({e[9045],405906,17,73,309,"キュルルゥ……遅いのだ。ゆずの出番に間に合わなくなるとこだったぞ！\n……別に、おまえの励ましが欲しかったわけじゃないのだ。ほ、ほら、出番の前に会う約束してたし、おまえを約束も守れない奴にするわけにはいかないからな！",200059,2,"deco/character/you_BL",1,3318,5000,1600,3856,2666,7333,9333,6666,14000,6666,2666,"you_bl",false,0},h)g[405907]=b({e[8045],405907,3,61,310,"「キュルルゥ、ハッピーハロウィンなのだ～～！\nどうだ、急に飛び出して来て、驚いたか？\nおまえのためにわざわざ練習したサプライズなのだ！\nちなみに、驚かせ方はまだまだたくさんのバリエーションを用意してあるぞ！\n見たければ、お菓子を差し出すのだ！」",200059,2,1,4864,5000,2380,3095,5333,8333,6500,10333,8000,8000,5333,false,false,0},h)g[406001]=b({e[16023],406001,false,141,311,false,200060,false,"deco/character/zekesi",302002,60,1,false,false,false,-90,"0,420,1","-30,20,1","20,20,1",false,false,false,"-40,0,1",false,false,false,false,1849,838,390,1143,688,2159,2993,1143,688,2159,1105},h)g[406002]=b({e[11034],406002,1,4,312,"「む、んむむぅ！ ……っ、おい！\n今のは『今くわえてる布を取れ』じゃなくて、『そこの布をよこせ』って意味だ！\nどんだけ長く一緒にいると思ってんだ、目配せの意図くらい読めてもいいだろーが。\n……オイ、なに怒ってんだよ、俺様とつうかあの仲になんのがそんなに嫌か！？」",200060,1,"deco/character/zekesi_0",302002,60,1899,888,389,807,548,2470,2592,807,582,2470,1261},h)g[406003]=b({e[24034],406003,11,132,313,"「俺様の刀に勝手に触んなっつっただろ！　いや、理由はそりゃ、触って怪我でもしたら大変なことになるからだよ。これでどついたりしたら、ピーピー泣いて面倒くせぇことになるに決まってら……ってマジでやるわけねぇだろが。」",200060,2,"deco/character/zekesi_YY",false,false,false,false,false,false,false,false,false,"0,30,0.97","0,30,0.97","60,60,0.9","0,30,0.97","0,30,0.97","0,0,0.97",1792,851,380,632,422,3403,3138,883,540,2901,1261},h)g[406004]=b({e[21034],406004,6,19,314,"「……ほら、手ぇ出せ。なんでって、引っ張ってやるために決まってんだろーが。日の光を照り返す雪と千本松、見てェだろ？　……別に、せっかくのハレの日だしな、テメェとこうして眺めんのも悪かねェ。そう思っただけだ！」",200060,2,"deco/character/zekesi_CJ",false,false,false,false,1,false,false,"1",false,"160,0,1",false,"280,-80,0.95",1901,827,399,437,450,3118,2647,545,526,2902,1261,1,1523,5000,800,985,5333,7166,7266,7333,15000,8000,10666},h)g[406101]=b({e[46059],406101,false,142,315,false,200061,false,"